from fractions import Fraction
from sympy import sqrt

def signs(quadrant):
    if quadrant == 1:
        return 1, 1
    elif quadrant == 2:
        return -1, 1
    elif quadrant == 3:
        return -1, -1
    else:
        return 1, -1

def quadrant_of(s, c):
    if s > 0 and c > 0:
        return 1
    elif s > 0:
        return 2
    elif c < 0:
        return 3
    return 4

def show(label, given, value, q):
    cs, ss = signs(q)
    if given == "sin":
        s, c = value, cs * sqrt(1 - value**2)
    else:
        s, c = ss * sqrt(1 - value**2), value
    print(f"{label}: {given} a = {value} in quadrant {q}, so sin a = {s}, cos a = {c}")
    s2 = 2 * s * c
    c2 = c**2 - s**2
    print(f"  sin 2a = 2 sin a cos a = {s2}")
    print(f"  cos 2a = cos^2 - sin^2 = {c2}, 2cos^2 - 1 = {2 * c**2 - 1}, 1 - 2sin^2 = {1 - 2 * s**2}")
    print(f"  tan 2a = {s2 / c2}, and 2a is in quadrant {quadrant_of(s2, c2)}")

show("Example 2", "sin", Fraction(3, 5), 1)
show("Example 3", "sin", Fraction(5, 13), 2)
show("Example 4", "cos", Fraction(1, 3), 1)
show("Quadrant III", "cos", Fraction(-3, 5), 3)

