practice.solution:
from fractions import Fraction
from sympy import sqrt

def signs(quadrant):
    if quadrant == 1:
        return 1, 1
    elif quadrant == 2:
        return -1, 1
    elif quadrant == 3:
        return -1, -1
    else:
        return 1, -1

def quadrant_of(s, c):
    if s > 0 and c > 0:
        return 1
    elif s > 0:
        return 2
    elif c < 0:
        return 3
    return 4

n = int(input())
for i in range(n):
    c = Fraction(int(input()), int(input()))
    q = int(input())
    s = signs(q)[1] * sqrt(1 - c**2)
    s2 = 2 * s * c
    c2 = 2 * c**2 - 1
    print(f"cos a = {c}: sin a = {s}, sin 2a = {s2}, cos 2a = {c2}, tan 2a = {s2 / c2}, quadrant {quadrant_of(s2, c2)}")
